146	    /// Subtracts an inactive thread. This cannot fail. It is invoked
147	    /// when a thread finds work and hence becomes active. It returns the
148	    /// number of sleeping threads to wake up (if any).
149	    ///
150	    /// See `add_inactive_thread`.
151	    #[inline]
152	    pub(super) fn sub_inactive_thread(&self) -> usize {
153	        let old_value = Counters::new(self.value.fetch_sub(ONE_INACTIVE, Ordering::SeqCst));
154	        debug_assert!(
155	            old_value.inactive_threads() > 0,
156	            "sub_inactive_thread: old_value {old_value:?} has no inactive threads",
157	        );
158	        debug_assert!(
159	            old_value.sleeping_threads() <= old_value.inactive_threads(),
160	            "sub_inactive_thread: old_value {:?} had {} sleeping threads and {} inactive threads",
161	            old_value,
162	            old_value.sleeping_threads(),
163	            old_value.inactive_threads(),
164	        );
165	
166	        // Current heuristic: whenever an inactive thread goes away, if
167	        // there are any sleeping threads, wake 'em up.
168	        let sleeping_threads = old_value.sleeping_threads();
169	        Ord::min(sleeping_threads, 2)
170	    }
171	
172	    /// Subtracts a sleeping thread. This cannot fail, but it is only
173	    /// safe to do if you you know the number of sleeping threads is
174	    /// non-zero (i.e., because you have just awoken a sleeping
175	    /// thread).
176	    #[inline]
177	    pub(super) fn sub_sleeping_thread(&self) {
178	        let old_value = Counters::new(self.value.fetch_sub(ONE_SLEEPING, Ordering::SeqCst));
179	        debug_assert!(
180	            old_value.sleeping_threads() > 0,
181	            "sub_sleeping_thread: old_value {old_value:?} had no sleeping threads",
182	        );
183	        debug_assert!(
184	            old_value.sleeping_threads() <= old_value.inactive_threads(),
185	            "sub_sleeping_thread: old_value {:?} had {} sleeping threads and {} inactive threads",
186	            old_value,
187	            old_value.sleeping_threads(),
188	            old_value.inactive_threads(),
189	        );
190	    }
191	
192	    #[inline]
193	    pub(super) fn try_add_sleeping_thread(&self, old_value: Counters) -> bool {
194	        debug_assert!(
195	            old_value.inactive_threads() > 0,
196	            "try_add_sleeping_thread: old_value {old_value:?} has no inactive threads",
197	        );
198	        debug_assert!(
199	            old_value.sleeping_threads() < THREADS_MAX,
200	            "try_add_sleeping_thread: old_value {old_value:?} has too many sleeping threads",
201	        );
202	
203	        let mut new_value = old_value;
204	        new_value.word += ONE_SLEEPING;
205	
206	        self.try_exchange(old_value, new_value, Ordering::SeqCst)
207	    }
208	}
